	        // Legacy W3C mouse events
	        $.MouseTracker.havePointerEvents = false;
	        $.MouseTracker.subscribeEvents.push( "mouseenter", "mouseleave", "mouseover", "mouseout", "mousedown", "mouseup", "mousemove" );
