	            // the full screen mode.
	            if ( !this.isFullPage() ) {
	                return this;
	            }

	            this.fullPageStyleWidth = this.element.style.width;
	            this.fullPageStyleHeight = this.element.style.height;
	            this.element.style.width = '100%';
	            this.element.style.height = '100%';

